function loadFetchEpicsToInput(opts) {
    opts = opts || {};
    var calls = {
        created: [],
        search: [],
        getIssue: [],
        writes: []
    };

    var tracker = {
        searchIssues: function (jql, searchOpts) {
            calls.search.push({ jql: jql, opts: searchOpts });
            return searchResultsFor(opts, jql);
